import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

import { PlaygroundApi } from '@coze-arch/bot-api';

const WORKSPACE_SPACE_ID_KEY = 'workspace-spaceId';
const WORKSPACE_SUB_MENU_KEY = 'workspace-subMenu';
const DEFAULT_WORKSPACE_SUB_MENU = 'develop';

const getDefaultSpaceID = (
  data: Awaited<ReturnType<typeof PlaygroundApi.GetSpaceListV2>>['data'],
) =>
  data?.recently_used_space_list?.[0]?.id || data?.bot_space_list?.[0]?.id || '';

const rememberWorkspace = (spaceID: string) => {
  try {
    window.localStorage.setItem(WORKSPACE_SPACE_ID_KEY, spaceID);
    window.localStorage.setItem(WORKSPACE_SUB_MENU_KEY, DEFAULT_WORKSPACE_SUB_MENU);
  } catch {
    // Incognito/private mode may reject localStorage; navigation can still proceed.
  }
};

export default function DefaultSpaceRedirect() {
  const navigate = useNavigate();
  const [message, setMessage] = useState('正在进入厦航办公助手工厂...');

  useEffect(() => {
    let cancelled = false;

    const redirectToWorkspace = async () => {
      try {
        const { data } = await PlaygroundApi.GetSpaceListV2({});
        const spaceID = getDefaultSpaceID(data);

        if (!spaceID) {
          setMessage('当前账号没有可用工作空间，请重新注册或联系管理员。');
          return;
        }

        rememberWorkspace(spaceID);

        if (!cancelled) {
          navigate(`/space/${spaceID}/develop`, { replace: true });
        }
      } catch {
        if (!cancelled) {
          setMessage('工作空间加载失败，请确认服务已启动后刷新页面。');
        }
      }
    };

    void redirectToWorkspace();

    return () => {
      cancelled = true;
    };
  }, [navigate]);

  return (
    <main
      style={{
        display: 'flex',
        minHeight: '100vh',
        alignItems: 'center',
        justifyContent: 'center',
        background: '#f7f8fa',
        color: '#1d1c23',
        fontSize: 16,
      }}
    >
      {message}
    </main>
  );
}
